presets.css:
/* =========================================================
   Puff · 樱花牛奶 × iOS 超淡玻璃
   ========================================================= */

.off-app {
  --off-list-bg:
    linear-gradient(
      145deg,
      rgba(255, 247, 250, 0.95),
      rgba(252, 249, 250, 0.90)
    );

  --off-list-border: rgba(255, 255, 255, 0.88);
  --off-list-radius: 22px;
  --off-list-ava-size: 52px;

  --off-pink: #efb8cb;
  --off-pink-light: #fce6ed;
  --off-pink-soft: rgba(245, 202, 217, 0.20);

  --off-glass: rgba(255, 255, 255, 0.62);
  --off-glass-heavy: rgba(255, 255, 255, 0.78);
  --off-glass-border: rgba(255, 255, 255, 0.82);

  --off-glass-shadow:
    0 8px 30px rgba(125, 88, 103, 0.055),
    inset 0 1px 0 rgba(255, 255, 255, 0.92);
}


/* 筛选 */

.off-inbox-filter {
  background: rgba(255, 255, 255, 0.45);
  border: 1px solid rgba(255, 255, 255, 0.72);
  border-radius: 999px;

  backdrop-filter: blur(20px) saturate(125%);
  -webkit-backdrop-filter: blur(20px) saturate(125%);
}

.off-inbox-filter button {
  color: #a69a9f;
  background: transparent;
  border-radius: 999px;
}

.off-inbox-filter button.on {
  color: #fff;

  background:
    linear-gradient(
      135deg,
      #f5c9d9,
      #efb5ca
    );

  box-shadow:
    0 4px 12px rgba(225, 164, 186, 0.18),
    inset 0 1px 0 rgba(255, 255, 255, 0.65);
}


/* 列表 */

.off-list {
  background: var(--off-list-bg);
  border: 1px solid var(--off-list-border);
  border-radius: var(--off-list-radius);
  overflow: hidden;

  backdrop-filter: blur(28px) saturate(125%);
  -webkit-backdrop-filter: blur(28px) saturate(125%);

  box-shadow: var(--off-glass-shadow);
}

.off-list-btn {
  padding: 15px 14px 15px 16px;
}

.off-list-btn:hover {
  background: rgba(245, 205, 220, 0.09);
}

.off-list-ava {
  width: var(--off-list-ava-size);
  height: var(--off-list-ava-size);

  border-radius: 50%;

  border: 2px solid rgba(255, 255, 255, 0.88);

  box-shadow:
    0 3px 12px rgba(120, 90, 102, 0.08),
    0 0 0 3px rgba(250, 218, 229, 0.20);
}

.off-list-body strong {
  font-size: 1.3rem;
  color: #4a4347;
  font-weight: 600;
}

.off-list-body span {
  opacity: 0.68;
  color: #91878b;
}

.off-list-go.is-new {
  font-size: 20px;
  font-weight: 300;
  color: #e7a9c0;
}


/* =========================================================
   当面共处
   ========================================================= */

.off-app.off-app-session {
  --off-card-user:
    linear-gradient(
      135deg,
      rgba(255, 231, 239, 0.66),
      rgba(255, 247, 250, 0.58)
    );

  --off-card-peer:
    rgba(255, 255, 255, 0.64);

  --off-card-border:
    rgba(255, 255, 255, 0.82);

  --off-card-shadow:
    0 8px 30px rgba(110, 75, 90, 0.055),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);

  --off-prose-font:
    var(--display),
    "Noto Serif SC",
    "Source Han Serif SC",
    Georgia,
    serif;

  --off-dock-bg:
    rgba(255, 250, 252, 0.70);

  color: var(--ink);
}


/* 无壁纸背景 */

.off-app.off-app-session:not(:has(.off-stage.has-bg)) .off-stage {
  background:
    radial-gradient(
      circle at 15% 15%,
      rgba(250, 220, 231, 0.48),
      transparent 35%
    ),
    radial-gradient(
      circle at 85% 80%,
      rgba(255, 235, 242, 0.62),
      transparent 40%
    ),
    #f7f3f5;
}


/* 顶栏 */

.off-app.off-app-session .off-stage-head {
  background:
    rgba(255, 251, 253, 0.58);

  border-bottom:
    1px solid rgba(255, 255, 255, 0.72);

  backdrop-filter:
    blur(26px) saturate(125%);

  -webkit-backdrop-filter:
    blur(26px) saturate(125%);
}

.off-app.off-app-session .off-stage-scene {
  font-weight: 500;
  letter-spacing: 0.04em;
}


/* 消息卡 */

.off-app.off-app-session .off-passage-sheet {
  background:
    var(--off-card-peer);

  border:
    1px solid var(--off-card-border);

  box-shadow:
    var(--off-card-shadow);

  border-radius:
    20px;

  backdrop-filter:
    blur(24px) saturate(125%);

  -webkit-backdrop-filter:
    blur(24px) saturate(125%);
}

.off-app.off-app-session
.off-passage.is-me
.off-passage-sheet {
  background:
    var(--off-card-user);

  border-color:
    rgba(242, 191, 208, 0.38);
}


/* 推演 */

.off-app .off-thinking-chip {
  background:
    rgba(255, 255, 255, 0.48);

  color:
    #a08f96;

  border:
    1px solid rgba(255, 255, 255, 0.70);

  border-radius:
    999px;

  padding:
    3px 11px;

  font-size:
    11px;

  backdrop-filter:
    blur(14px);

  -webkit-backdrop-filter:
    blur(14px);
}


/* 正文 */

.off-app.off-app-session .off-prose-para,
.off-app.off-app-session .off-prose-narr,
.off-app.off-app-session .off-prose-plain,
.off-app.off-app-session .off-prose-dial {
  font-family: var(--off-prose-font);
  line-height: 1.85;
  font-size: 14.5px;
  color: var(--ink);
}

.off-app.off-app-session .off-prose-dial {
  font-weight: 500;
}

.off-app.off-app-session
.off-passage.is-me
.off-prose-dial {
  font-weight: 400;
}


/* 底部 */

.off-app.off-app-session .off-stage-dock {
  background:
    var(--off-dock-bg);

  backdrop-filter:
    blur(28px) saturate(130%);

  -webkit-backdrop-filter:
    blur(28px) saturate(130%);

  border-top:
    1px solid rgba(255, 255, 255, 0.76);
}


/* 输入框 */

.off-compose-bar {
  background:
    rgba(255, 255, 255, 0.70);

  border:
    1px solid rgba(255, 255, 255, 0.88);

  border-radius:
    999px;

  backdrop-filter:
    blur(24px) saturate(125%);

  -webkit-backdrop-filter:
    blur(24px) saturate(125%);

  box-shadow:
    0 5px 20px rgba(110, 75, 90, 0.055),
    inset 0 1px 0 rgba(255, 255, 255, 0.92);
}


/* 发送 */

.off-compose-send {
  background:
    linear-gradient(
      135deg,
      #f4c7d8,
      #edb4ca
    );

  color: #fff;

  border-radius: 50%;

  box-shadow:
    0 4px 12px rgba(220, 157, 181, 0.20),
    inset 0 1px 0 rgba(255, 255, 255, 0.65);
}


/* 滚动条 */

.off-app ::-webkit-scrollbar {
  width: 5px;
  height: 5px;
}

.off-app ::-webkit-scrollbar-thumb {
  background: rgba(224, 175, 195, 0.22);
  border-radius: 999px;
}

.off-app ::-webkit-scrollbar-track {
  background: transparent;
}
